import { useCallback, useEffect, useState } from "react";

import {
  type Instrument,
  type ReadingExercise,
  type ReadingOptions,
  generateReadingExercise,
} from "@/lib/engine";

/** The current sight-reading melody. Generated by the engine whenever the
 * melody options or the instrument change (tempo does not), or on demand. */
export function useReadingExercise(options: ReadingOptions, instrument: Instrument) {
  const [exercise, setExercise] = useState<ReadingExercise | null>(null);
  const [error, setError] = useState<string | null>(null);
  const key = JSON.stringify([options, instrument]);

  const regenerate = useCallback(async () => {
    try {
      setExercise(await generateReadingExercise());
      setError(null);
    } catch (e) {
      setExercise(null);
      setError(String(e));
    }
  }, []);

  // `key` changes only after the engine has saved the new settings, so the
  // engine generates from the values shown.
  useEffect(() => {
    regenerate();
  }, [key, regenerate]);

  return { exercise, error, regenerate };
}
